package fixture

import "testing"

func TestFib(t *testing.T) {
	if got := Fib(0); got != 0 {
		t.Fatalf("Fib(0) = %d", got)
	}
	if got := Fib(10); got != 55 {
		t.Fatalf("Fib(10) = %d, want 55", got)
	}
}
